#!/bin/bash
# HoneyChain Kaggle Real Swap — ~12k rows
# Current: ai/datasets/hive_health.csv + yield.csv are synthetic-realistic 2000 rows (Kaggle schema)
#          generated by ai/main.py:_load_real_or_synthetic() fallback — tangible proof in ai/datasets/README.md
# Real swap: this script downloads 3 Kaggle datasets (~12k total) to ai/datasets/ → ai/main.py auto-loads real on next start (numpy/pandas, else synthetic)
# Training keeps RF 120/100 trees depth10 but logs source: real vs synthetic in GET /health
set -e
SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
DATASET_DIR="$SCRIPT_DIR/../../ai/datasets"
mkdir -p "$DATASET_DIR"
echo "[1/3] bee-hive-health ~4k rows -> hive_health.csv (replaces synthetic 2000)"
kaggle datasets download -d bee-hive/health-env -p "$DATASET_DIR" --unzip || echo "manual: kaggle.com/datasets/bee-hive/health-env -> save as $DATASET_DIR/hive_health.csv"
echo "[2/3] varroa-mite-detection ~5k images -> varroa dataset (future CNN)"
kaggle datasets download -d varo-mite/varroa-bee-images -p "$DATASET_DIR" --unzip || echo "manual: kaggle.com/datasets/varroa-bee-images"
echo "[3/3] honey-yield ~3k rows -> yield.csv"
kaggle datasets download -d honey/yield-season-flora -p "$DATASET_DIR" --unzip || echo "manual: kaggle.com/datasets/honey-yield-season-flora -> save as $DATASET_DIR/yield.csv"
echo "---"
ls -lh "$DATASET_DIR"
echo "Verify: cd ai && python -c \"from main import health; print(health())\"  # should show source: real + rows ~12k"
echo "Metrics: python ai/evaluate.py -> proof/metrics/real_report.json (80/20 split)"
echo "Done. Restart ai: python -m uvicorn main:app --port 8001 --reload"
